wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Only a published digest marks its considered items as seen; an
        // unpublished run records nothing. `recorded` counts items newly
        // written this run, so it is 0 when every id was already seen.
        if published.published {
            for id in &published.considered {
                if state_rw::get(id).is_none() {
                    state_rw::put(id, &published.date);
                    recorded += 1;
                }
            }
        }

        // ensures recorded >= 0 holds trivially: recorded is a u32.
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
